def ans(R,s,c):f=s["f"];v=T._you(pv(s,c));c=T._you(c);ts=f["am"] if s["e"]=="me" and f["am"] else f["ao"] or f["am"];t=R.choices(ts,[3]+[1]*(len(ts)-1))[0];return fill(t,s,c,v,True)
def absn(R,s):f=s["f"];d=(f["dm"] if s["e"]=="me" and f["dm"] else f["do"] or f["dm"]).format(e=s["e"],x=T._you(s["x"] or ""));t=pick(R,ABS);return t.format(d=d)
def hedge(R,s,d):w=s["f"]["w"];c1,c2=s["c"],d["c"];return R.choice(HDP).format(v1=T._you(f"{s['p']} {c1}".strip()),v2=T._you(f"{d['p']} {c2}".strip())) if w in ("why","how") else R.choice(HDG).format(c1=T._you(c1),c2=T._you(c2),C1=cap(T._you(c1)))
def ack(R,s,c):k=s["f"]["k"];return R.choice(ECHO).format(c=c,C=cap(c)) if R.random()<.18 and len(c)<40 and k in ("color","name","home","origin","dest","work","fav","job","breed","model") else R.choice(ACK["allergy"] if k=="allergy" else ACK[s["f"]["w"]])
def corr(R,s,c1):
 c2=s["c"];t,vb=stm(R,s);w=s["f"]["w"];k=R.randrange(6 if w in ("what","when") else 5);lc=lambda x:x if x[:2] in ("I ","I'") or x[:1].isupper() and x.split(" ")[0] not in ("My","The","Oh,","Just","Heads","These") else x[:1].lower()+x[1:]
 return (["Actually, "+lc(t),"Wait, sorry, "+lc(t),"Correction: "+t,"Scratch that, "+lc(t),t[:-1]+f", not {c1}." if w in ("what","where") else "Sorry, I got that wrong. "+t,"Oops, I meant %s."%(pv(s,c2) if w=="when" else c2)][k]),k==5
def real(stmts,q):
 st=T.Store()
 for x in stmts:T.observe(st,x)
 r=T.recall(st,q,"both",unk=True);return r["line"],st
LRE=re.compile(r"^Memory: (.+?), ([a-z]+): (.+?)\.$")
def lval(l):m=LRE.match(l or "");return m.groups() if m else None
def okv(a,g,bad=()):A,G_=set(nn(a).split())-{"the","a","an","in","at","on","to","my"},set(nn(g).split())-{"the","a","an","in","at","on","to","my"};return bool(G_) and G_<=A and len(A-G_)<=1 and not any(nn(b) and set(nn(b).split())<=A for b in bad if set(nn(b).split())-G_)
def fline(s,stmts,q,c,vb,bad=(),st=None):
 l,_=real(stmts,q);m=lval(l);lb=m[0] if m else "";good=bool(m) and "(unsure)" not in l and m[2]!="unknown" and okv(m[2],gval(s,c),bad) and (lb==T.label(s["le"]) or s["le"]=="me" and (lb=="you" or lb.startswith("you (")) or bool(s["x"]) and lb in ("you","your "+re.sub(r"^(?:the|my|a|an) ","",s["x"])))
 st is not None and st.update(["tm_line_real" if good else "tm_line_gold"]);return (l,m[2]) if good else (gline(s,c,vb=vb if s["le"]=="me" and s["f"]["w"]!="what" else ""),gval(s,c))
def uline(s,stmts,q,st=None):
 l,S_=real(stmts,q);g=gline(s,"",True);qa=T.ask(q,T._last(S_),list(S_.ents()),S_.names,S_.lp);r=T.line(qa["ents"][0],qa["w"],qa["attr"],"unknown") if qa and qa["ents"] and qa["w"]==s["f"]["w"] and (qa["ents"][0]==s["le"] or qa["ents"][0]=="me" and s["le"]=="me") else g
 st is not None and st.update(["tm_uline_"+("ask" if r!=g else "gold")+("_real_same" if l==r else "")]);return r
def fill_h(R,k):D=S["D"];return [tuple(B.a1(x) for x in R.choice(D)[:2]) for _ in range(k)]
def weave(R,facts,k):H=fill_h(R,k);n=len(H)+len(facts);sl=set(R.sample(range(n),len(facts)));fi,hi=iter(facts),iter(H);return [next(fi) if j in sl else next(hi) for j in range(n)]
def lkey(l):return l.rsplit(":",1)[0]
def dstr(R,s,n,mode="ent"):
 o=[];av=[s["c"]];f=s["f"];kc=lambda e:"kin" if e in KIN else "pet" if e in PET else "obj" if e in OBJ else "me"
 if mode=="attr":C=[g for g in FR if g["k"]!=f["k"] and ((g["sm"] and s["e"]=="me") or g["so"] and s["e"]!="me" and any(a==kc(s["e"]) for a,_ in ekw(g)) and (g["k"]!="breed" or s["e"] in BREED))]
 else:C=[f] if f["so"] and any(a!="me" for a,_ in ekw(f)) or f["xs"] or f["ek"] in ("kept","event","rt","fav") else [g for g in FW[f["w"]] if g["k"]!=f["k"]]
 for _ in range(n):
  for _ in range(30):
   if not C:return o
   g=R.choice(C);d=slot(R,g,e=s["e"],avoid=av) if mode=="attr" else slot(R,g,avoid=av)
   if mode=="attr" or (d["le"],d["x"],d["f"]["k"])!=(s["le"],s["x"],f["k"]):break
  else:return o
  av.append(d["c"]);o.append(d)
 return o
def fits(t):x,_=B.render(t);return len(S["tk"].enc(x.encode("ascii","ignore")))<=B.CTX-8
def has(v,r):return bool(nn(v)) and f" {nn(v)} " in f" {nn(r)} "
def mk(R,st,src,q,H,rc,reply,must=(),bad=(),inc=""):
 m=B.smem(q,H)
 if m["reply"]:st[src+"_skip_mem_reply"]+=1;return None
 Tt,u,pb=B.srv(q,m["hist"],(),rc);us={x for x,_ in Tt}
 if any(x not in us for x in must):st[src+"_skip_fact_trimmed"]+=1;return None
 if any(has(b,reply) for b in bad if not (inc and has(b,inc))) or inc and not has(T._you(inc),reply):st[src+"_skip_reply_check"]+=1;return None
 t=Tt+[(u,reply)];x="".join(f"User: {a}\nAdam: {b}\n\n" for a,b in t);y=B.dirt(x) or ("eval_line" if any(B.nrm(z) in B.EQS for z in [q]+[a for a,_ in Tt]) else "") or ("too_long" if not fits(t) else "")
 if y:st[src+"_skip_"+y]+=1;return None
 return t,[q],pb
def pack(R,st,src,sh,q,H,rc,reply,must=(),bad=(),inc=""):r=mk(R,st,src,q,H,rc,reply,must,bad,inc);return None if r is None else (r[0],r[1],r[2],sh)
def tmem(st):
 R=random.Random(B.SEED+71);out=[];n=B.N("TMEM_N",8000);cnt=collections.Counter();g=0;tries=0;Q=collections.Counter()
 while len(out)<n and tries<n*6:
  g+=1;w=WS[g%5];s=slot(R,w=w);fs=sorted(FORMS,key=lambda k:(cnt[k]-FORMS[k]*(len(out)+2),R.random()))[:2];ql=qs(R,s,4)
  for j,fm in enumerate(fs):
   tries+=1;r=form(R,st,s,fm,para(R,ql[j%len(ql)]))
   if r is None:st["tmem_drop_"+fm]+=1;continue
   t,qq,pb,sh=r;cnt[fm]+=1;Q[nn(qq[0])]+=1;st["tmem_form_"+fm]+=1;st["tmem_w_"+w]+=1;st["tmem_frame_"+s["f"]["k"]]+=1;out.append(B.ex("tmem",f"t{g}.{j}",t,qq,"umem",lo=1,np=0,sh="tmem:"+sh,pb=pb,sk=f"tmem|{g}"))
 st["tmem_groups"]=g;st["tmem_tries"]=tries;st["tmem_distinct_questions"]=len(Q);return out
def vbl(s,vb):return vb if s["le"]=="me" and s["f"]["w"]!="what" else ""
def form(R,st,s,fm,q):
 f=s["f"];same=R.random()<.5;k=R.choices((0,1,2,3),(25,35,25,15))[0]
 if fm in ("ans","corr"):
  D=dstr(R,s,R.choices((0,1,2),(30,45,25))[0]);t0,vb=stm(R,s);c=s["c"];bad=[d["c"] for d in D];facts=[(t0,ack(R,s,c))]+[(stm(R,d)[0],ack(R,d,d["c"])) for d in D];R.shuffle(facts)
  if fm=="corr":
   s2={**s,**{a:b for a,b in slot(R,f,e=s["e"],x=s["x"],avoid=[c]+bad).items() if a in ("p","c")}};c2=s2["c"];ct,el=corr(R,s2,c);i=[j for j,x in enumerate(facts) if x[0]==t0][0];ki=R.random()<.7;j=i+1 if el else R.randint(i+1,len(facts));F2=facts[:j]+[(ct,R.choice(CACK))]+facts[j:]
   l,lv=fline(s2,[x for x,_ in F2],q,c2,vb,[c]+bad,st);H=weave(R,F2 if ki else facts,k);return pack(R,st,"tmem",f"corr:{f['w']}:{'hist' if ki else 'linebeats'}",q,H,[l],ans(R,s2,lv),[t0]+([ct] if ki else []),[c]+bad,lv)
  l,lv=fline(s,[x for x,_ in facts],q,c,vb,bad,st);H=weave(R,facts,k) if same else fill_h(R,k)
  return pack(R,st,"tmem",f"ans:{f['w']}:{'same' if same else 'next'}"+(":distr" if D else ""),q,H,[l],ans(R,s,lv),[t0] if same else [],bad,lv)
 if fm in ("unk","none"):
  D=dstr(R,s,R.choices((0,1,2),(35,40,25))[0]);E=dstr(R,s,1,"attr") if s["e"]!="me" or R.random()<.5 else [];A=D+E;facts=[(stm(R,d)[0],ack(R,d,d["c"])) for d in A];R.shuffle(facts);bad=[d["c"] for d in A]
  if fm=="unk":l=uline(s,[x for x,_ in facts],q,st);H=weave(R,facts,k) if same else fill_h(R,k);return pack(R,st,"tmem",f"unk:{f['w']}:{'same' if same else 'next'}",q,H,[l],absn(R,s),[],bad)
  hs=R.random()<.6;H=weave(R,facts,k) if hs else fill_h(R,k);return pack(R,st,"tmem",f"none:{f['w']}"+(":distr" if hs and A else ""),q,H,[],absn(R,s),[],bad)
 if fm=="unsure":
  D=dstr(R,s,1)
  if not D:return None
  d=D[0];l=gline(s,s["c"],alt=gval(d));hd=R.random()<.5;H=weave(R,[(stm(R,d)[0],ack(R,d,d["c"]))],k) if hd else fill_h(R,k);st["tm_line_gold_unsure"]+=1
  return pack(R,st,"tmem",f"unsure:{f['w']}"+(":distr" if hd else ""),q,H,[l],hedge(R,s,d),[],[],gval(s,s["c"]))
 uk=R.random()<.25;t0,vb=stm(R,s);lt=gline(s,s["c"],uk,vb=vbl(s,vb))
 for md in (("attr","ent") if R.random()<.3 else ("ent","attr")):
  O=dstr(R,s,1,md)
  if O:ot,ovb=stm(R,O[0]);o=O[0];lo=gline(o,o["c"],vb=vbl(o,ovb))
  if O and lkey(lo)!=lkey(lt) and not (o["le"]==s["le"] and o["f"]["k"]==f["k"]):break
 else:return None
 rc=[lt,lo];R.shuffle(rc);st["tm_line_gold_two"]+=1;same=R.random()<.4;facts=[(ot,ack(R,o,o["c"]))]+([] if uk else [(t0,ack(R,s,s["c"]))]);R.shuffle(facts);H=weave(R,facts,k) if same else fill_h(R,k)
 return pack(R,st,"tmem",f"two:{f['w']}:{'unk' if uk else 'val'}:{md}",q,H,rc,absn(R,s) if uk else ans(R,s,gval(s)),[t0] if same and not uk else [],[o["c"]],"" if uk else gval(s))
def cmem(st):
 R=random.Random(B.SEED+72);out=[];n=B.N("CMEM_N",6000);g=0;tries=0;Q=collections.Counter()
 while len(out)<n and tries<n*6:
  g+=1;w=WS[g%5];s=slot(R,w=w);tries+=2;ql=qs(R,s,2);q1,q2=para(R,ql[0]),para(R,ql[-1]);nm=R.choices(("ent","attr","none"),(45,35,20))[0]
  NM=dstr(R,s,R.choice((1,2)),nm) if nm!="none" else [];nm=nm if NM else "none";fm=[(stm(R,d)[0],ack(R,d,d["c"])) for d in NM];k=R.choices((0,1,2,3),(20,35,30,15))[0];H0=weave(R,fm,k)
  t0,_=stm(R,s);cr=R.random()<.2;bad=[d["c"] for d in NM];s2={**s,**{a:b for a,b in slot(R,s["f"],e=s["e"],x=s["x"],avoid=[s["c"]]+bad).items() if a in ("p","c")}} if cr else s;ct,el=corr(R,s2,s["c"]) if cr else (None,False)
  i=len(H0) if R.random()<.25 else R.randint(0,len(H0));HK=H0[:i]+[(t0,ack(R,s,s["c"]))]+H0[i:]
  if cr:j=i+1 if el else R.randint(i+1,len(HK));HK=HK[:j]+[(ct,R.choice(CACK))]+HK[j:]
  gv=gval(s2)
  a=pack(R,st,"cmem",f"known:{w}:{nm}"+(":corr" if cr else "")+(":last" if i==len(H0) and not cr else ""),q1,HK,[],ans(R,s2,gv),[t0]+([ct] if cr else []),bad+([s["c"]] if cr else []),gv)
  b=pack(R,st,"cmem",f"unknown:{w}:{nm}",q2,H0,[],absn(R,s),[],bad+[s["c"]]) if a else None
  if a is None or b is None:st["cmem_pair_dropped"]+=1;continue
  for j,(t,qq,pb,sh) in enumerate((a,b)):Q[nn(qq[0])]+=1;st["cmem_"+sh.split(":")[0]]+=1;st["cmem_w_"+w]+=1;st["cmem_near_miss_"+nm]+=1;out.append(B.ex("cmem",f"c{g}.{j}",t,qq,"umem",lo=1,np=0,sh="cmem:"+sh,pb=pb,sk=f"cmem|{g}"))
 st["cmem_pairs"]=len(out)//2;st["cmem_tries"]=tries;st["cmem_distinct_questions"]=len(Q);return out
def meta(st,cnt):
 A=lambda p:{k[len(p):]:v for k,v in sorted(st.items()) if k.startswith(p)}
 return {"what":"v7 = v6 (token, mask, index and attribution rows byte-identical, same source order) + tmem (toroid memory-line use) + cmem (contrastive memory twins) (ADAM-T-SFT7): teach ADAM-T to use the memory it is given and to say it does not know when memory has nothing",
 "toroid_module":{"file":"amni/serve/user_toroid.py","sha1":__import__("hashlib").sha1(open(T.__file__,"rb").read()).hexdigest()},"why":"docs/adam_t/user_toroid.md section 11 (an oracle toroid line gets only 40-49% zero-shot, the 30M model treats 'Memory:' as a topic) and docs/adam_t/rca_grounding.md (SFT v3 answers 'haven't told me' on 36% of memory questions it knows; round-2 SFT invents memories on 57% of no-fact questions)",
 "tmem":{"examples":{"train":cnt["tmem"]["train_examples"],"hold":cnt["tmem"]["hold_examples"]},"target_mix":FORMS,"forms":A("tmem_form_"),"by_w":A("tmem_w_"),"by_frame":A("tmem_frame_"),"groups":st["tmem_groups"],"distinct_questions":st["tmem_distinct_questions"],"line_source":{"real_toroid_line":st["tm_line_real"],"gold_line_real_extractor_missed":st["tm_line_gold"],"unknown_lines":A("tm_uline_"),"unsure_gold":st["tm_line_gold_unsure"],"two_line_gold":st["tm_line_gold_two"]},
  "rules":{"prompt":"User: [history turns] <Memory line(s)> <question>\\nAdam: via adam_t_client.template (the serve's toroid rc slot: the line goes immediately before the question; legacy preamble dropped as with AMNI_UMEM_TOROID_PRE=0); history passes through adam_t_client._mem (user_memory.turn) exactly as the serve does","line":"rendered by amni/serve/user_toroid.line(): the fact statements are ingested by a fresh user_toroid.Store via observe() and the question goes through recall(tier='both', unk=True); that real line is used when its label is the asked entity and its value is the gold value (<=1 extra word, no distractor value); otherwise the gold slot is rendered with line() in the same format ('Memory: <label>, <attr or W>: <value>.', 'you (<verb>)' for the user's own where/when/why/how slots). unknown lines use user_toroid.ask() on the question (attr from the question parse) as respond(unk=True) does; unsure lines are line(..., unsure=<2nd>) with no verb as in respond()","forms":{"ans":"line with the value; reply copies the value (templates per slot, incl. the user_toroid.say() shapes 'Your car is red.', 'It's red.'); same session (fact and 0-2 same-type distractor facts in the history) or next session (history holds only chat)","corr":"old value, then a correction; the line holds the latest value (real supersession when the toroid got it); 70% keep the correction turn in the history, 30% only the old value is in the history ('the line beats the history'); the reply never contains the old value","unk":"'<label>, <attr>: unknown.' line for an entity the user has told other facts about (or the user); reply is an honest 'You haven't told me ...' (10 templates) and never names a distractor value","none":"no line and no relevant history (other entities' same-type facts may be present); reply abstains","unsure":"'<v1> or <v2> (unsure)' line; reply hedges between them, v1 first","two":"two memory lines (asked entity and another entity with the same slot, or the same entity with another slot), random order; reply comes from the line whose label and slot match the question; 25% of the asked lines are 'unknown' and the reply abstains without copying the other line"},"paraphrase":"5-15 question templates per slot and entity type (self/other), plus 13 conversational prefixes, 5% lowercased, 8% without '?'; each form of a group uses a different question template","groups":"each sampled slot gives 2 forms (the two most under-quota forms), so the same slot/question appears with and without a usable memory; a group shares one hold/train split","coverage":"5 W (uniform) x %d slot frames; self, kin, pets, objects, events, stored items; ~30%% multi-token or invented values; values from the v19 generator pools (D3/D3-dev values excluded) plus own CC0 pools; every toroid_dev.jsonl answer/fact value excluded (%d values)"%(len(FR),S.get("dev_values",0))}},
 "cmem":{"examples":{"train":cnt["cmem"]["train_examples"],"hold":cnt["cmem"]["hold_examples"]},"pairs":st["cmem_pairs"],"kinds":{"known":st["cmem_known"],"unknown":st["cmem_unknown"]},"by_w":A("cmem_w_"),"near_miss":A("cmem_near_miss_"),"distinct_questions":st["cmem_distinct_questions"],"rules":"contrastive twins in the same-session serve shape (history only, no memory line): the known twin has the fact as a user turn with a short Adam acknowledgement (25% right before the question, 20% old value then a correction; reply = latest value); the unknown twin has the same history without that turn; both twins keep the same near-miss facts (45% another entity with the same slot, 35% the same entity with another slot, 20% none) and ask the same slot with two different paraphrases; the unknown reply abstains and never names a near-miss value; a twin pair is kept or dropped together and shares one hold/train split"},
 "precheck":"every tmem/cmem example is pre-checked before it is kept (13-gram non-exempt, 8-gram ADAM-T/NQ/D3/emergency incl. data/adam_t/eval/toroid, 6-gram chat suite, 6-gram toroid_dev.jsonl, exact eval user line incl. toroid_dev questions, <=CTX tokens, required fact turns survive the serve history fit) and redrawn on a hit; the main decontam pass runs again after","skips":{k:v for k,v in sorted(st.items()) if "_skip_" in k and k.startswith(("tmem","cmem"))},"cmem_pairs_dropped":st["cmem_pair_dropped"]}
